/* SUP-2272 and SUP-3677 */
(function () {
      if ( typeof win.CustomEvent === "function" ) return false;
      function CustomEvent ( event, params ) {
        params = params || { bubbles: false, cancelable: false, detail: null };
        var evt = document.createEvent( 'CustomEvent' );
        evt.initCustomEvent( event, params.bubbles, params.cancelable, params.detail );
        return evt;
      }
    win.CustomEvent = CustomEvent;
})();
win.ggevents.push({'inscreen.load': function (data) {
    document.body.dispatchEvent(new CustomEvent('gumgum-inscreen-load'));
    document.querySelector('.adthrive-sticky.adthrive-footer').setAttribute('style', 'visibility: hidden !important;');

}});
win.ggevents.push({'inscreen.close': function (data) {
    if(data.userRequested) {
        document.body.dispatchEvent(new CustomEvent('gumgum-inscreen-close'));
        G.Bean.fire(G.container, 'closedISAd');
    }
     document.querySelector('.adthrive-sticky.adthrive-footer').setAttribute('style', 'visibility: visible !important;');
}});
